node -e '
const re=/\p{Nd}/u; const runs=[]; let start=-1;
for(let cp=0;cp<=0x10FFFF;cp++){
  if(cp>=0xD800&&cp<=0xDFFF){ if(start>=0){runs.push([start,cp-1]);start=-1;} continue; }
  const isd=re.test(String.fromCodePoint(cp));
  if(isd){ if(start<0) start=cp; } else { if(start>=0){runs.push([start,cp-1]); start=-1;} }
}
if(start>=0)runs.push([start,0x10FFFF]);
const bad=runs.filter(r=>r[1]-r[0]+1!==10);
console.log("runs:",runs.length,"bad:",JSON.stringify(bad));
// merge into contiguous groups of 10 starting points
const starts=[]; for(const [a,b] of runs){ for(let s=a;s<=b;s+=10) starts.push(s); }
console.log("starts:",starts.length);
console.log(JSON.stringify(starts));
'
